laboratory.referenceCode:
#include <iostream>

int main() {
    long long bytes{1001};
    long long blockBytes{1000};
    // Scaffold from Module 1: reject invalid bounds before division.
    if (bytes < 0 || bytes > 1'000'000'000'000LL || blockBytes < 1 || blockBytes > 4096) {
        std::cout << "invalid\n";
        return 0;
    }
    long long fullBlocks = bytes / blockBytes;
    long long remainderBytes = bytes % blockBytes;
    long long neededBlocks = (bytes + blockBytes - 1) / blockBytes;
    std::cout << "full=" << fullBlocks << '\n';
    std::cout << "remainder=" << remainderBytes << '\n';
    std::cout << "needed=" << neededBlocks << '\n';
    return 0;
}
